function main(input: { amount: number }) {
  return { level: input.amount >= 100000 ? "部長" : "課長" };
}

export function main(input) {
  return { level: input.amount >= 100000 ? "部長" : "課長" };
}

function main(input) {
  const map = {};
  for (const it of input.items) {
    const d = it.data;
    const rep = d.rep || '(担当者未設定)';
    if (!map[rep]) map[rep] = { rep: rep, visits: 0, prospect: 0 };
    map[rep].visits += Number(d.visits || 0);
    map[rep].prospect += Number(d.prospect || 0);
  }
  const rows = Object.keys(map).sort().map(k => ({ week_start: input.start, rep: map[k].rep, visits: map[k].visits, prospect: map[k].prospect }));
  let table = '| 担当者 | 訪問件数 | 見込み額 |\n|---|---|---|\n';
  for (const r of rows) table += '| ' + r.rep + ' | ' + r.visits + ' | ' + r.prospect + ' |\n';
  if (rows.length === 0) table = '（先週の日報はありませんでした）';
  return { week_start: input.start, rows: rows, table_text: table, count: input.items.length };
}

export function main(input) {
  const totals = {};
  const notes = [];
  for (const it of input.items || []) {
    const d = it.data || {};
    const rep = d.rep || "（担当者なし）";
    if (!totals[rep]) totals[rep] = { rep: rep, visits: 0, prospect: 0 };
    totals[rep].visits += Number(d.visits) || 0;
    totals[rep].prospect += Number(d.prospect) || 0;
    if (d.note) notes.push(rep + " " + (d.report_date || "") + ": " + d.note);
  }
  const reps = Object.keys(totals).sort();
  const rows = reps.map(function (k) {
    const r = totals[k];
    return { week_start: input.start, rep: r.rep, visits: r.visits, prospect: r.prospect };
  });
  const lines = rows.map(function (r) {
    return r.rep + ": 訪問 " + r.visits + " 件、見込み額 " + r.prospect;
  });
  return { rows: rows, text: lines.join("\n") + "\n\n所感:\n" + notes.join("\n"), count: (input.items || []).length };
}

